    ('0x4e637ce5eb8a0d626e2f0ff1b72b831e4ad3a7bf', 59000000000000000000)
),
dbbal AS (
  SELECT
    o.wallet,
    o.reserve_wei::numeric AS reserve_wei,
    COALESCE(ppc.balance, 0)::numeric * 1000000000000000000
      + COALESCE(p.bal, 0)::numeric                          AS db_wei
  FROM onchain o
  LEFT JOIN player_poker_chips ppc
    ON ppc.wallet_address = o.wallet
  LEFT JOIN (
    SELECT LOWER(wallet_address) AS w, SUM(balance) AS bal
    FROM players GROUP BY LOWER(wallet_address)
  ) p ON p.w = o.wallet
),
calc AS (
  SELECT
    wallet, reserve_wei, db_wei,
    LEAST(db_wei, reserve_wei)            AS owed_backed,
    GREATEST(0, db_wei - reserve_wei)     AS owed_excess,
    GREATEST(0, reserve_wei - db_wei)     AS dead_locked
  FROM dbbal
)
-- ===== SUMMARY (one row — this is the number that matters) =====
SELECT
  ROUND(SUM(reserve_wei) / 1000000000000000000, 2) AS total_reserves,
  ROUND(SUM(db_wei)      / 1000000000000000000, 2) AS current_liability,
  ROUND(SUM(owed_backed) / 1000000000000000000, 2) AS payable_from_pool,
  ROUND(SUM(owed_excess) / 1000000000000000000, 2) AS owe_from_hotwallet,
  ROUND(SUM(dead_locked) / 1000000000000000000, 2) AS dead_locked_loss
FROM calc;

